-- Full workflow on existing test report, entirely rolled back. No Storage SQL writes.
begin;
do $$
declare provider_id integer; provider_auth uuid; pic_auth uuid; foreign_auth uuid; d public.dokumen; v public.dokumen_versi; qid integer; current_version integer; base_state jsonb; state jsonb; snapshot1 jsonb; snapshot2 jsonb; trail1 bigint; trail2 bigint; r record; policy_expr text; allowed boolean; initial_report_version integer; changed_file_version integer;
begin
 select u.pengguna_id,u.auth_user_id into provider_id,provider_auth from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) where pr.nama='penyedia_jasa' limit 1;
 select doc.* into d from public.dokumen doc join public.jenis_dokumen j using(jenis_dokumen_id) join public.dokumen_versi dv on dv.dokumen_id=doc.dokumen_id and dv.versi_ke=doc.versi_aktif join storage.objects o on o.bucket_id=dv.bucket_id and o.name=dv.object_path where j.kode='LAPORAN_PENDAHULUAN' and doc.status='TERSEDIA' and o.owner_id=provider_auth::text order by doc.dokumen_id limit 1;
 if d.dokumen_id is null then raise exception 'Need a test report uploaded by provider';end if;
 select * into v from public.dokumen_versi where dokumen_id=d.dokumen_id and versi_ke=d.versi_aktif;
 initial_report_version:=v.dok_versi_id;
 select u.auth_user_id into pic_auth from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) join public.paket_kontrak p on p.paket_id=d.paket_id where pr.nama='pic_balai' and pp.scope_balai_id=p.balai_id and (pp.scope_paket_id is null or pp.scope_paket_id=p.paket_id) limit 1;
 select u.auth_user_id into foreign_auth from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) join public.paket_kontrak p on p.paket_id=d.paket_id where pr.nama='pic_balai' and pp.scope_balai_id<>p.balai_id limit 1;
 if pic_auth is null or foreign_auth is null then raise exception 'Need scoped and foreign PIC fixtures';end if;
 select pg_get_expr(polwithcheck,polrelid) into policy_expr from pg_policy where polname='dokumen_storage_insert_provider' and polrelid='storage.objects'::regclass;
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);execute 'set local role authenticated';
 base_state:=public.baca_checklist_persiapan(d.paket_id);current_version:=(base_state#>>'{pengisian,versi}')::int;qid:=(base_state#>>'{pengisian,pengisian_id}')::int;
 if base_state#>>'{pengisian,status}'<>'DRAFT' then raise exception 'Test requires a draft test package';end if;
 -- Unlinking the report must prevent submission, without imposing mandatory answers.
 state:=public.tautkan_bukti_persiapan(d.paket_id,current_version,15,null);current_version:=(state#>>'{pengisian,versi}')::int;
 begin perform public.ajukan_persiapan(d.paket_id,current_version);raise exception 'Missing report allowed';exception when invalid_parameter_value then null;end;
 state:=public.tautkan_bukti_persiapan(d.paket_id,current_version,15,d.dokumen_id);current_version:=(state#>>'{pengisian,versi}')::int;
 begin perform public.ajukan_persiapan(d.paket_id,current_version-1);raise exception 'Stale submit allowed';exception when serialization_failure then null;end;
 execute 'reset role';
 alter table public.audit_trail add constraint test_submit_audit_failure check(aksi<>'SUBMIT_PREPARATION') not valid;
 execute 'set local role authenticated';
 begin perform public.ajukan_persiapan(d.paket_id,current_version);raise exception 'Submit audit failure not raised';exception when check_violation then null;end;
 if public.baca_pengajuan_persiapan(d.paket_id)->>'status'<>'DRAFT' then raise exception 'Failed submit changed status';end if;
 execute 'reset role';alter table public.audit_trail drop constraint test_submit_audit_failure;
 execute 'set local role authenticated';
 state:=public.ajukan_persiapan(d.paket_id,current_version);current_version:=(state->>'versi')::int;trail1:=(state#>>'{pengajuan,pengajuan_id}')::bigint;snapshot1:=state#>'{pengajuan,snapshot}';
 if state->>'status'<>'DIAJUKAN' or snapshot1->>'laporan_dok_versi_id'<>v.dok_versi_id::text or snapshot1#>>'{checklist,pengisian,status}'<>'DIAJUKAN' or snapshot1#>>'{checklist,pengisian,versi}'<>current_version::text then raise exception 'Submitted snapshot/status mismatch';end if;
 if state#>>'{aturan,validasi_kelengkapan_resmi_aktif}'<>'false' then raise exception 'Official gate invented';end if;
 -- All provider mutation paths, including direct RPCs, are locked.
 begin perform public.ubah_paket_draft(d.paket_id,'{"nama_ppk":"Should fail"}');raise exception 'Package edit unlocked';exception when object_not_in_prerequisite_state then null;end;
 begin perform public.simpan_checklist_persiapan(d.paket_id,current_version,'[{"item_id":1,"jawaban":"Ya"}]');raise exception 'Answers unlocked';exception when object_not_in_prerequisite_state then null;end;
 begin perform public.tautkan_bukti_persiapan(d.paket_id,current_version,15,null);raise exception 'Link unlocked';exception when object_not_in_prerequisite_state then null;end;
 begin perform public.daftar_dokumen_persiapan(d.paket_id,'LAPORAN_PENDAHULUAN','Should fail',v.object_path,v.nama_file,v.ukuran_byte,v.hash_file);raise exception 'New upload unlocked';exception when object_not_in_prerequisite_state then null;end;
 begin perform public.tambah_versi_dokumen_persiapan(d.paket_id,d.dokumen_id,d.versi_aktif,v.object_path,v.nama_file,v.ukuran_byte,v.hash_file);raise exception 'Version upload unlocked';exception when object_not_in_prerequisite_state then null;end;
 execute 'select ('||policy_expr||') from (select $1::text as bucket_id,$2::text as name,$3::text as owner_id) objects' into allowed using 'dokumen-persiapan',d.paket_id||'/00000000-0000-4000-8000-000000000099.pdf',provider_auth::text;
 if allowed then raise exception 'Storage upload policy unlocked';end if;
 begin perform public.review_persiapan(d.paket_id,current_version,'DISETUJUI','');raise exception 'Provider reviewed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',foreign_auth::text,true);execute 'set local role authenticated';
 begin perform public.baca_pengajuan_persiapan(d.paket_id);raise exception 'Foreign PIC reads snapshot';exception when no_data_found then null;end;
 begin perform public.review_persiapan(d.paket_id,current_version,'DISETUJUI','');raise exception 'Foreign PIC reviewed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',pic_auth::text,true);execute 'set local role authenticated';
 if public.baca_pengajuan_persiapan(d.paket_id)#>'{pengajuan,snapshot}'<>snapshot1 then raise exception 'PIC did not see frozen snapshot';end if;
 begin perform public.review_persiapan(d.paket_id,current_version,'PERLU_REVISI',' ');raise exception 'Revisi without note';exception when invalid_parameter_value then null;end;
 begin perform public.review_persiapan(d.paket_id,current_version-1,'DISETUJUI','');raise exception 'Stale review';exception when serialization_failure then null;end;
 execute 'reset role';alter table public.audit_trail add constraint test_review_audit_failure check(aksi<>'REVIEW_PREPARATION') not valid;
 execute 'set local role authenticated';
 begin perform public.review_persiapan(d.paket_id,current_version,'PERLU_REVISI','Temporary revision');raise exception 'Review audit failure not raised';exception when check_violation then null;end;
 if public.baca_pengajuan_persiapan(d.paket_id)->>'status'<>'DIAJUKAN' or (public.baca_pengajuan_persiapan(d.paket_id)->'review')<>'null'::jsonb then raise exception 'Failed review changed state/decision';end if;
 execute 'reset role';alter table public.audit_trail drop constraint test_review_audit_failure;
 execute 'set local role authenticated';
 state:=public.review_persiapan(d.paket_id,current_version,'PERLU_REVISI','Temporary revision');current_version:=(state->>'versi')::int;
 if state->>'status'<>'PERLU_REVISI' or state#>>'{review,dok_versi_id}'<>initial_report_version::text or state#>'{pengajuan,snapshot}'<>snapshot1 then raise exception 'Revision decision not bound to submitted version';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);execute 'set local role authenticated';
 state:=public.simpan_checklist_persiapan(d.paket_id,current_version,'[{"item_id":1,"jawaban":"Tidak","keterangan":"Temporary revision answer"}]');current_version:=(state#>>'{pengisian,versi}')::int;
 perform public.ubah_paket_draft(d.paket_id,'{"nama_ppk":"Temporary revision PPK"}');
 if public.baca_pengajuan_persiapan(d.paket_id)#>'{pengajuan,snapshot}'<>snapshot1 then raise exception 'Editing changed frozen submission';end if;
 -- Public metadata only: free existing test object's path, then register another version within rollback.
 execute 'reset role';update public.dokumen_versi set object_path=object_path||'.rollback-fixture' where dok_versi_id=v.dok_versi_id;
 execute 'set local role authenticated';
 state:=public.tambah_versi_dokumen_persiapan(d.paket_id,d.dokumen_id,d.versi_aktif,v.object_path,v.nama_file,v.ukuran_byte,v.hash_file);changed_file_version:=(state#>>'{versi,dok_versi_id}')::int;
 current_version:=(public.baca_pengajuan_persiapan(d.paket_id)->>'versi')::int;
 state:=public.ajukan_persiapan(d.paket_id,current_version);current_version:=(state->>'versi')::int;trail2:=(state#>>'{pengajuan,pengajuan_id}')::bigint;snapshot2:=state#>'{pengajuan,snapshot}';
 if trail2=trail1 or snapshot2->>'laporan_dok_versi_id'<>changed_file_version::text or state->'review'<>'null'::jsonb then raise exception 'Resubmit did not capture fresh version/reset current review';end if;
 execute 'reset role';
 if (select nilai_baru from public.audit_trail where trail_id=trail1)<>snapshot1 or (select count(*) from public.persetujuan_dokumen where pengajuan_trail_id=trail1)<>1 then raise exception 'Earlier submission/decision history lost';end if;
 perform set_config('request.jwt.claim.sub',pic_auth::text,true);execute 'set local role authenticated';
 state:=public.review_persiapan(d.paket_id,current_version,'DISETUJUI','Temporary approval');current_version:=(state->>'versi')::int;
 if state->>'status'<>'DISETUJUI' or state#>>'{review,dok_versi_id}'<>changed_file_version::text then raise exception 'Approval bound to wrong report';end if;
 begin perform public.review_persiapan(d.paket_id,current_version,'DISETUJUI','');raise exception 'Double decision allowed';exception when object_not_in_prerequisite_state then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);execute 'set local role authenticated';
 begin perform public.ubah_paket_draft(d.paket_id,'{"nama_ppk":"Should still fail"}');raise exception 'Approved package editable';exception when object_not_in_prerequisite_state then null;end;
 if (select status from public.paket_kontrak where paket_id=d.paket_id)<>'DRAFT' then raise exception 'Whole package lifecycle changed';end if;
 execute 'reset role';
 if has_function_privilege('anon','public.ajukan_persiapan(integer,integer)','EXECUTE') or has_function_privilege('anon','public.review_persiapan(integer,integer,text,text)','EXECUTE') or has_function_privilege('anon','public.baca_pengajuan_persiapan(integer)','EXECUTE') then raise exception 'Anonymous RPC granted';end if;
end $$;
rollback;
select 'PASS: submit/revise/edit/version/resubmit/approve, frozen evidence snapshots and exact-version decisions, missing report, stale requests, all mutation/Storage locks, scoped PIC, provider denial, audit atomicity and preserved history. All data restored; Storage unchanged.' as verification;
